import { eq, sql } from 'drizzle-orm';

// Built once at module load
const userById = db
  .select()
  .from(users)
  .where(eq(users.id, sql.placeholder('id')))
  .prepare('user_by_id');

const postsByAuthor = db
  .select({ id: posts.id, title: posts.title })
  .from(posts)
  .where(eq(posts.authorId, sql.placeholder('authorId')))
